"""Week-aware scheduler (WFM-231). Used by clients whose config sets `scheduler: week`.

`greedy.py` places templates one local day at a time and audits the rules afterwards. This scheduler
keeps week state per agent, so the rules in the newer contracts are enforced while placing:

  * rest: at least `min_rest_hours` elapsed between the end of one shift and the start of the next
    (both neighbours are checked, because placement is not in day order);
  * split templates only for the contracts in `split_contracts` (default: every contract);
  * weekly elapsed-hour caps, `max_consecutive_days`, one template per local day, skills;
  * per-queue floors (`min_cover`, wfm/constraints.py), as a hard requirement on gross cover;
  * breaks placed by `break.placement`: `midpoint` (service default) or `surplus` — inside the break
    window, in the planning interval where the queue's gross coverage surplus (agents on the queue
    ignoring breaks minus agents required) is largest; ties go to the interval with the most net cover.

Three passes, all deterministic:
  1. build: place the (day, template, queue) whose slots cover the most uncovered requirement per
     slot on the eligible agent with the fewest other skills, then the fewest hours;
  2. repair: place breaks, then keep adding the shift that recovers the most intervals that are short
     net of breaks, while total hours stay within `max_hours_ratio` x required agent-hours;
  3. prune: drop shifts whose removal loses no interval on any queue and keeps every floor, and, if
     hours are still above the bound, the shifts that cost the fewest intervals.
"""
from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

import pandas as pd

from wfm import constraints
from wfm.ingest.loader import local_days
from wfm.roster import Agent
from wfm.scheduler.greedy import Shift, place_breaks
from wfm.scheduler.templates import Template, eligible, templates_for
from wfm.staffing.required import in_hours


@dataclass(frozen=True)
class _Cand:
    day: date
    tpl: Template
    queue: str
    segs: tuple[tuple[datetime, datetime], ...]
    slots: tuple[int, ...]          # grid indices covered

    @property
    def hours(self) -> float:
        return sum((e - s).total_seconds() for s, e in self.segs) / 3600.0


class _Week:
    """Requirement, cover and per-agent state for one client-week."""

    def __init__(self, req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str):
        self.cfg = cfg
        self.tz = cfg["tz"]
        self.grid = sorted(set(req["interval_start_utc"]))
        self.idx = {t: i for i, t in enumerate(self.grid)}
        self.n = len(self.grid)
        self.queues = list(dict.fromkeys(req["queue"]))
        self.required = {q: [0] * self.n for q in self.queues}
        for r in req.itertuples(index=False):
            self.required[r.queue][self.idx[r.interval_start_utc]] = int(r.required)
        self.floor = {q: [constraints.floor(q, t, cfg) for t in self.grid] for q in self.queues}
        # intervals that count toward attainment: inside the queue's operating hours
        self.operating = {q: [in_hours(t, cfg, q) for t in self.grid] for q in self.queues}
        self.weight = constraints.weight(cfg)
        self.agents = sorted(agents, key=lambda a: a.agent_id)
        self.by_id = {a.agent_id: a for a in self.agents}
        self.caps = cfg["weekly_hours"]
        self.max_run = cfg["max_consecutive_days"]
        rest = cfg.get("min_rest_hours")
        self.rest = timedelta(hours=float(rest)) if rest else None
        split_ok = cfg.get("split_contracts")
        self.split_ok = None if split_ok is None else set(split_ok)
        self.days = local_days(week, self.tz)
        self.gross = {q: [0] * self.n for q in self.queues}
        self.cross = {q: [0] * self.n for q in self.queues}
        self.shifts: list[tuple[str, _Cand]] = []
        self.by_agent: dict[str, dict[date, _Cand]] = defaultdict(dict)
        self.hours: dict[str, float] = defaultdict(float)
        self.cands = self._candidates()
        self.req_hours = sum(sum(v) for v in self.required.values()) * cfg["interval_minutes"] / 60.0

    # ---- candidates and agent feasibility -------------------------------------------------------
    def _candidates(self) -> list[_Cand]:
        out = []
        for day in self.days:
            for tpl in templates_for(self.cfg):
                segs = tuple(tpl.segments_utc(day, self.tz))
                slots = tuple(self.idx[t] for s, e in segs for t in self.grid if s <= t < e)
                if not slots:
                    continue
                for q in self.queues:
                    out.append(_Cand(day, tpl, q, segs, slots))
        return out

    def _contract_ok(self, a: Agent, tpl: Template) -> bool:
        if not eligible(tpl, a.contract):
            return False
        return not tpl.is_split or self.split_ok is None or a.contract in self.split_ok

    def feasible(self, a: Agent, c: _Cand) -> bool:
        if c.queue not in a.skills or not self._contract_ok(a, c.tpl):
            return False
        mine = self.by_agent[a.agent_id]
        if c.day in mine:
            return False
        if self.hours[a.agent_id] + c.hours > self.caps[a.contract] + 1e-9:
            return False
        days = set(mine) | {c.day}
        run, d = 1, c.day - timedelta(days=1)
        while d in days:
            run, d = run + 1, d - timedelta(days=1)
        d = c.day + timedelta(days=1)
        while d in days:
            run, d = run + 1, d + timedelta(days=1)
        if run > self.max_run:
            return False
        if self.rest is not None:
            before = [x for dd, x in mine.items() if dd < c.day]
            after = [x for dd, x in mine.items() if dd > c.day]
            if before and c.segs[0][0] - max(before, key=lambda x: x.day).segs[-1][1] < self.rest:
                return False
            if after and min(after, key=lambda x: x.day).segs[0][0] - c.segs[-1][1] < self.rest:
                return False
        return True

    def pick_agent(self, c: _Cand) -> Agent | None:
        cands = [a for a in self.agents if self.feasible(a, c)]
        if not cands:
            return None
        # keep flexible (multi-skilled) agents for later; then spread hours
        return min(cands, key=lambda a: (len(a.skills & set(self.queues)), self.hours[a.agent_id], a.agent_id))

    # ---- placing and removing -------------------------------------------------------------------
    def _apply(self, aid: str, c: _Cand, sign: int) -> None:
        others = self.by_id[aid].skills & set(self.queues) - {c.queue}
        for i in c.slots:
            self.gross[c.queue][i] += sign
            for o in others:
                self.cross[o][i] += sign

    def add(self, aid: str, c: _Cand) -> None:
        self.shifts.append((aid, c))
        self.by_agent[aid][c.day] = c
        self.hours[aid] += c.hours
        self._apply(aid, c, +1)

    def remove(self, k: int) -> tuple[str, _Cand]:
        aid, c = self.shifts.pop(k)
        del self.by_agent[aid][c.day]
        self.hours[aid] -= c.hours
        self._apply(aid, c, -1)
        return aid, c

    def total_hours(self) -> float:
        return sum(c.hours for _, c in self.shifts)

    # ---- requirement on gross cover (build pass) ------------------------------------------------
    def short(self, q: str, i: int, on_queue: float) -> float:
        return constraints.uncovered(self.required[q][i], self.floor[q][i], on_queue, self.cross[q][i], self.cfg)

    # ---- breaks and net cover -------------------------------------------------------------------
    def breaks(self) -> dict[int, int | None]:
        """Break slot per shift (index into self.shifts), by the configured placement rule."""
        rule = self.cfg["break"]
        if rule.get("placement", "midpoint") != "surplus":
            return self._breaks_midpoint(rule)
        length = timedelta(minutes=rule["minutes"])
        lo, hi = (timedelta(hours=h) for h in rule["window_hours"])
        taken = {q: [0] * self.n for q in self.queues}
        out: dict[int, int | None] = {}
        order = sorted(range(len(self.shifts)), key=lambda k: (self.shifts[k][1].segs[0][0], self.shifts[k][0]))
        for k in order:
            aid, c = self.shifts[k]
            out[k] = None
            if c.hours < rule["min_shift_hours"]:
                continue
            start = c.segs[0][0]
            fits = [i for i in c.slots
                    if start + lo <= self.grid[i] <= start + hi
                    and any(s <= self.grid[i] and self.grid[i] + length <= e for s, e in c.segs)]
            if not fits:
                continue
            q = c.queue
            best = max(self.gross[q][i] - self.required[q][i] for i in fits)
            tied = [i for i in fits if self.gross[q][i] - self.required[q][i] == best]
            i = max(tied, key=lambda j: (self.gross[q][j] - taken[q][j] - self.required[q][j], -j))
            taken[q][i] += 1
            out[k] = i
        return out

    def _breaks_midpoint(self, rule: dict) -> dict[int, int | None]:
        out = {}
        length = timedelta(minutes=rule["minutes"])
        for k, (aid, c) in enumerate(self.shifts):
            out[k] = None
            if c.hours < rule["min_shift_hours"]:
                continue
            fits = [i for i in c.slots if any(s <= self.grid[i] and self.grid[i] + length <= e for s, e in c.segs)]
            if fits:
                mid = c.segs[0][0] + timedelta(hours=c.hours / 2)
                out[k] = min(fits, key=lambda i: (abs((self.grid[i] - mid).total_seconds()), i))
        return out

    def net(self, brk: dict[int, int | None]) -> dict[str, list[int]]:
